'use strict';

/**
* Compute the Airy functions of the first and second kind, Ai(x) and Bi(x), and their first derivatives, Ai'(x) and Bi'(x).
*
* @module @stdlib/math/base/special/airy
*
* @example
* var airy = require( '@stdlib/math/base/special/airy' );
*
* var v = airy( 0.0 );
* // returns [ ~0.355, ~-0.259, ~0.615, ~0.448 ]
*
* v = airy( 1.0 );
* // returns [ ~0.135, ~-0.159, ~1.207, ~0.932 ]
*
* v = airy( -1.0 );
* // returns [ ~0.536, ~-0.01, ~0.104, ~0.592 ]
*
* v = airy( Infinity );
* // returns [ 0, 0, Infinity, Infinity ]
*
* v = airy( -Infinity );
* // returns [ NaN, NaN, NaN, NaN ]
*
* v = airy( NaN );
* // returns [ NaN, NaN, NaN, NaN ]
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var assign = require( './assign.js' );
var main = require( './main.js' );
var ai = require( './ai.js' );
var aip = require( './aip.js' );
var bi = require( './bi.js' );
var bip = require( './bip.js' );


// MAIN //

setReadOnly( main, 'assign', assign );
setReadOnly( main, 'ai', ai );
setReadOnly( main, 'aip', aip );
setReadOnly( main, 'bi', bi );
setReadOnly( main, 'bip', bip );


// EXPORTS //

module.exports = main;
